8	   version 2 of the License, or (at your option) any later version.
9	*/
10	
11	/* this code supports:
12	 * reading:
13	 *     uncompressed and run length encoded indexed, grey and color tga files.
14	 *     image types 1, 2, 3, 9, 10 and 11.
15	 *     only RGB color maps with no more than 256 colors.
16	 *     pixel formats 8, 16, 24 and 32.
17	 * writing:
18	 *     uncompressed true color tga files
19	 */
20	
21	#include "tga_p.h"
22	
23	#include <assert.h>
24	
25	#include <QImage>
26	#include <QDataStream>
27	#include <QDebug>
28	
29	typedef quint32 uint;
30	typedef quint16 ushort;
31	typedef quint8 uchar;
32	
33	namespace   // Private.
34	{
35	
36	// Header format of saved files.
37	uchar targaMagic[12] = { 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, 0 };
38	
39	enum TGAType {
40	    TGA_TYPE_INDEXED        = 1,
41	    TGA_TYPE_RGB            = 2,
42	    TGA_TYPE_GREY           = 3,
43	    TGA_TYPE_RLE_INDEXED    = 9,
44	    TGA_TYPE_RLE_RGB        = 10,
45	    TGA_TYPE_RLE_GREY       = 11
46	};
47	
48	#define TGA_INTERLEAVE_MASK 0xc0
49	#define TGA_INTERLEAVE_NONE 0x00
50	#define TGA_INTERLEAVE_2WAY 0x40
51	#define TGA_INTERLEAVE_4WAY 0x80
52	
53	#define TGA_ORIGIN_MASK     0x30
54	#define TGA_ORIGIN_LEFT     0x00
55	#define TGA_ORIGIN_RIGHT    0x10
56	#define TGA_ORIGIN_LOWER    0x00
57	#define TGA_ORIGIN_UPPER    0x20
58	
59	/** Tga Header. */
60	struct TgaHeader {
61	    uchar id_length;
62	    uchar colormap_type;
63	    uchar image_type;
64	    ushort colormap_index;
65	    ushort colormap_length;
66	    uchar colormap_size;
67	    ushort x_origin;
68	    ushort y_origin;
69	    ushort width;
70	    ushort height;
71	    uchar pixel_size;
72	    uchar flags;
73	
74	    enum { SIZE = 18 }; // const static int SIZE = 18;
75	};
76	
77	static QDataStream &operator>> (QDataStream &s, TgaHeader &head)
78	{
79	    s >> head.id_length;
80	    s >> head.colormap_type;
81	    s >> head.image_type;
82	    s >> head.colormap_index;
83	    s >> head.colormap_length;
84	    s >> head.colormap_size;
85	    s >> head.x_origin;
86	    s >> head.y_origin;
87	    s >> head.width;
88	    s >> head.height;
89	    s >> head.pixel_size;
90	    s >> head.flags;
91	    /*qDebug() << "id_length: " << head.id_length << " - colormap_type: " << head.colormap_type << " - image_type: " << head.image_type;
92	    qDebug() << "colormap_index: " << head.colormap_index << " - colormap_length: " << head.colormap_length << " - colormap_size: " << head.colormap_size;
93	    qDebug() << "x_origin: " << head.x_origin << " - y_origin: " << head.y_origin << " - width:" << head.width << " - height:" << head.height << " - pixelsize: " << head.pixel_size << " - flags: " << head.flags;*/
94	    return s;
95	}
96	
97	static bool IsSupported(const TgaHeader &head)
98	{
99	    if (head.image_type != TGA_TYPE_INDEXED &&
100	            head.image_type != TGA_TYPE_RGB &&
101	            head.image_type != TGA_TYPE_GREY &&
102	            head.image_type != TGA_TYPE_RLE_INDEXED &&
103	            head.image_type != TGA_TYPE_RLE_RGB &&
104	            head.image_type != TGA_TYPE_RLE_GREY) {
105	        return false;
106	    }
107	    if (head.image_type == TGA_TYPE_INDEXED ||
108	            head.image_type == TGA_TYPE_RLE_INDEXED) {
109	        if (head.colormap_length > 256 || head.colormap_size != 24 || head.colormap_type != 1) {
110	            return false;
111	        }
112	    }
113	    if (head.image_type == TGA_TYPE_RGB ||
114	            head.image_type == TGA_TYPE_GREY ||
115	            head.image_type == TGA_TYPE_RLE_RGB ||
116	            head.image_type == TGA_TYPE_RLE_GREY) {
117	        if (head.colormap_type != 0) {
118	            return false;
119	        }
120	    }
121	    if (head.width == 0 || head.height == 0) {
122	        return false;
123	    }
124	    if (head.pixel_size != 8 && head.pixel_size != 16 &&
125	            head.pixel_size != 24 && head.pixel_size != 32) {
126	        return false;
127	    }
128	    return true;
129	}
130	
131	struct Color555 {
132	    ushort b : 5;
133	    ushort g : 5;
134	    ushort r : 5;
135	};
136	
137	struct TgaHeaderInfo {
138	    bool rle;
139	    bool pal;
140	    bool rgb;
141	    bool grey;
142	
143	    TgaHeaderInfo(const TgaHeader &tga) : rle(false), pal(false), rgb(false), grey(false)
144	    {
145	        switch (tga.image_type) {
146	        case TGA_TYPE_RLE_INDEXED:
147	            rle = true;
148	        Q_FALLTHROUGH();
149	        // no break is intended!
150	        case TGA_TYPE_INDEXED:
151	            pal = true;
152	            break;
153	
154	        case TGA_TYPE_RLE_RGB:
155	            rle = true;
156	        Q_FALLTHROUGH();
157	        // no break is intended!
158	        case TGA_TYPE_RGB:
159	            rgb = true;
160	            break;
161	
162	        case TGA_TYPE_RLE_GREY:
163	            rle = true;
164	        Q_FALLTHROUGH();
165	        // no break is intended!
166	        case TGA_TYPE_GREY:
167	            grey = true;
168	            break;
169	
170	        default:
171	            // Error, unknown image type.
172	            break;
173	        }
174	    }
175	};
176	
177	static bool LoadTGA(QDataStream &s, const TgaHeader &tga, QImage &img)
178	{
179	    // Create image.
180	    img = QImage(tga.width, tga.height, QImage::Format_RGB32);
181	
182	    TgaHeaderInfo info(tga);
183	
184	    // Bits 0-3 are the numbers of alpha bits (can be zero!)
185	    const int numAlphaBits = tga.flags & 0xf;
186	    // However alpha exists only in the 32 bit format.
187	    if ((tga.pixel_size == 32) && (tga.flags & 0xf)) {
188	        img = QImage(tga.width, tga.height, QImage::Format_ARGB32);
189	
190	        if (numAlphaBits > 8) {
191	            return false;
192	        }
193	    }
194	
195	    uint pixel_size = (tga.pixel_size / 8);
196	    qint64 size = qint64(tga.width) * qint64(tga.height) * pixel_size;
197	
198	    if (size < 1) {
199	//          qDebug() << "This TGA file is broken with size " << size;
200	        return false;
201	    }
202	
203	    // Read palette.
204	    char palette[768];
205	    if (info.pal) {
206	        // @todo Support palettes in other formats!
207	        const int size = 3 * tga.colormap_length;
208	        const int dataRead = s.readRawData(palette, size);
209	        if (dataRead < size) {
210	            memset(&palette[dataRead], 0, size - dataRead);
211	        }
212	    }
213	
214	    // Allocate image.
215	    uchar *const image = reinterpret_cast<uchar*>(malloc(size));
216	    if (!image) {
217	        return false;
218	    }
219	
220	    bool valid = true;
221	
222	    if (info.rle) {
223	        // Decode image.
224	        char *dst = (char *)image;
225	        qint64 num = size;
226	
227	        while (num > 0) {
228	            if (s.atEnd()) {
229	                valid = false;
230	                break;
231	            }
232	
233	            // Get packet header.
234	            uchar c;
235	            s >> c;
236	
237	            uint count = (c & 0x7f) + 1;
238	            num -= count * pixel_size;
239	            if (num < 0) {
240	                valid = false;
241	                break;
242	            }
243	
244	            if (c & 0x80) {
245	                // RLE pixels.
246	                assert(pixel_size <= 8);
247	                char pixel[8];
248	                s.readRawData(pixel, pixel_size);
249	                do {
250	                    memcpy(dst, pixel, pixel_size);
251	                    dst += pixel_size;
252	                } while (--count);
253	            } else {
254	                // Raw pixels.
255	                count *= pixel_size;
256	                s.readRawData(dst, count);
257	                dst += count;
258	            }
259	        }
260	    } else {
261	        // Read raw image.
262	        const int dataRead = s.readRawData((char *)image, size);
263	        if (dataRead < size) {
264	            memset(&image[dataRead], 0, size - dataRead);
265	        }
266	    }
267	
268	    if (!valid) {
269	        free(image);
270	        return false;
271	    }
272	
273	    // Convert image to internal format.
274	    int y_start, y_step, y_end;
275	    if (tga.flags & TGA_ORIGIN_UPPER) {
276	        y_start = 0;
277	        y_step = 1;
278	        y_end = tga.height;
279	    } else {
280	        y_start = tga.height - 1;
281	        y_step = -1;
282	        y_end = -1;
283	    }
284	
285	    uchar *src = image;
286	
287	    for (int y = y_start; y != y_end; y += y_step) {
288	        QRgb *scanline = (QRgb *) img.scanLine(y);
289	
290	        if (info.pal) {
291	            // Paletted.
292	            for (int x = 0; x < tga.width; x++) {
293	                uchar idx = *src++;
294	                scanline[x] = qRgb(palette[3 * idx + 2], palette[3 * idx + 1], palette[3 * idx + 0]);
295	            }
296	        } else if (info.grey) {
297	            // Greyscale.
298	            for (int x = 0; x < tga.width; x++) {
299	                scanline[x] = qRgb(*src, *src, *src);
300	                src++;
301	            }
302	        } else {
303	            // True Color.
304	            if (tga.pixel_size == 16) {
305	                for (int x = 0; x < tga.width; x++) {
306	                    Color555 c = *reinterpret_cast<Color555 *>(src);
307	                    scanline[x] = qRgb((c.r << 3) | (c.r >> 2), (c.g << 3) | (c.g >> 2), (c.b << 3) | (c.b >> 2));
308	                    src += 2;
309	                }
310	            } else if (tga.pixel_size == 24) {
311	                for (int x = 0; x < tga.width; x++) {
312	                    scanline[x] = qRgb(src[2], src[1], src[0]);
313	                    src += 3;
314	                }
315	            } else if (tga.pixel_size == 32) {
316	                for (int x = 0; x < tga.width; x++) {
317	                    // ### TODO: verify with images having really some alpha data
318	                    const uchar alpha = (src[3] << (8 - numAlphaBits));
319	                    scanline[x] = qRgba(src[2], src[1], src[0], alpha);
320	                    src += 4;
321	                }
322	            }
323	        }
324	    }
325	
326	    // Free image.
327	    free(image);
328	
329	    return true;
330	}
331	
332	} // namespace
333	
334	TGAHandler::TGAHandler()
335	{
336	}
337	
338	bool TGAHandler::canRead() const
339	{
340	    if (canRead(device())) {
341	        setFormat("tga");
342	        return true;
343	    }
344	    return false;
345	}
346	
347	bool TGAHandler::read(QImage *outImage)
348	{
349	    //qDebug() << "Loading TGA file!";
350	
351	    QDataStream s(device());
352	    s.setByteOrder(QDataStream::LittleEndian);
353	
354	    // Read image header.
355	    TgaHeader tga;
356	    s >> tga;
357	    s.device()->seek(TgaHeader::SIZE + tga.id_length);
358	
359	    // Check image file format.
360	    if (s.atEnd()) {
361	//         qDebug() << "This TGA file is not valid.";
362	        return false;
363	    }
364	
365	    // Check supported file types.
366	    if (!IsSupported(tga)) {
367	//         qDebug() << "This TGA file is not supported.";
368	        return false;
369	    }
370	
371	    QImage img;
372	    bool result = LoadTGA(s, tga, img);
373	
374	    if (result == false) {
375	//         qDebug() << "Error loading TGA file.";
376	        return false;
377	    }
378	
379	    *outImage = img;
380	    return true;
381	}
382	
383	bool TGAHandler::write(const QImage &image)
384	{
385	    QDataStream s(device());
386	    s.setByteOrder(QDataStream::LittleEndian);
387	
388	    const QImage &img = image;
389	    const bool hasAlpha = (img.format() == QImage::Format_ARGB32);
390	    for (int i = 0; i < 12; i++) {
391	        s << targaMagic[i];
392	    }
393	
394	    // write header
395	    s << quint16(img.width());   // width
396	    s << quint16(img.height());   // height
397	    s << quint8(hasAlpha ? 32 : 24);   // depth (24 bit RGB + 8 bit alpha)
398	    s << quint8(hasAlpha ? 0x24 : 0x20);   // top left image (0x20) + 8 bit alpha (0x4)
399	
400	    for (int y = 0; y < img.height(); y++)
401	        for (int x = 0; x < img.width(); x++) {
402	            const QRgb color = img.pixel(x, y);
403	            s << quint8(qBlue(color));
404	            s << quint8(qGreen(color));
405	            s << quint8(qRed(color));
406	            if (hasAlpha) {
407	                s << quint8(qAlpha(color));
408	            }
409	        }
410	
411	    return true;
412	}
413	
414	bool TGAHandler::canRead(QIODevice *device)
415	{
416	    if (!device) {
417	        qWarning("TGAHandler::canRead() called with no device");
418	        return false;
419	    }
420	
421	    qint64 oldPos = device->pos();
422	    QByteArray head = device->read(TgaHeader::SIZE);
423	    int readBytes = head.size();
424	
425	    if (device->isSequential()) {
426	        for (int pos = readBytes - 1; pos >= 0; --pos) {
427	            device->ungetChar(head[pos]);
428	        }
429	    } else {
430	        device->seek(oldPos);
431	    }
432	
433	    if (readBytes < TgaHeader::SIZE) {
434	        return false;
435	    }
436	
437	    QDataStream stream(head);
438	    stream.setByteOrder(QDataStream::LittleEndian);
439	    TgaHeader tga;
440	    stream >> tga;
441	    return IsSupported(tga);
442	}
443	
444	QImageIOPlugin::Capabilities TGAPlugin::capabilities(QIODevice *device, const QByteArray &format) const
445	{
446	    if (format == "tga") {
447	        return Capabilities(CanRead | CanWrite);
448	    }
449	    if (!format.isEmpty()) {
450	        return {};
451	    }
452	    if (!device->isOpen()) {
453	        return {};
454	    }
455	
456	    Capabilities cap;
457	    if (device->isReadable() && TGAHandler::canRead(device)) {
458	        cap |= CanRead;
459	    }
460	    if (device->isWritable()) {
461	        cap |= CanWrite;
462	    }
463	    return cap;
464	}
465	
466	QImageIOHandler *TGAPlugin::create(QIODevice *device, const QByteArray &format) const
467	{
468	    QImageIOHandler *handler = new TGAHandler;
469	    handler->setDevice(device);
470	    handler->setFormat(format);
471	    return handler;
472	}
